export function eventExpenseGroups(groups,eventId){return groups.filter(g=>g.event_id===eventId).sort((a,b)=>a.created_at_millis-b.created_at_millis||a.id.localeCompare(b.id));}
export function selectedExpenseGroup(groups,eventId,selectedId){const list=eventExpenseGroups(groups,eventId);return list.find(g=>g.id===selectedId)||list[0];}
export function ledgerNavigation(groups,expenses,eventId,selectedId,esc,money){const list=eventExpenseGroups(groups,eventId);if(list.length<2)return '';return `<section class="card"><h3>Shared expenses for this event</h3><p class="muted">Earlier versions created separate ledgers. All are available below; existing splits and settlements have not been merged or changed.</p><div class="row">${list.map((g,i)=>`<button class="${g.id===selectedId?'':'quiet'}" data-action="expense-ledger" data-id="${g.id}">${i===0?'Shared event ledger':'Existing ledger '+(i+1)} · ${esc(g.currency)}</button>`).join('')}</div><details><summary>View every expense across existing ledgers</summary>${expenses.filter(x=>list.some(g=>g.id===x.group_id)&&!x.deleted_at_millis).sort((a,b)=>b.created_at_millis-a.created_at_millis).map(x=>`<p><strong>${esc(x.title)}</strong> · ${money(x.amount_minor,x.currency)}<br><small>Added by ${esc(x.created_by_name)}</small><br><button class="quiet" data-action="expense-ledger" data-id="${x.group_id}">Open this ledger</button></p>`).join('')||'<p>No expenses added yet.</p>'}</details></section>`;}
